#!/usr/bin/env python3
"""Regenerate the host-test fixture routes (``routes_fixture.{h,cpp}``).

Issue #91: the firmware FSM-logic host tests (``reanchor_at_wall``,
``reanchor_at_wall_strict``, ``path_tracker_reset_arrival``,
``return_to_node_dispatch``, and the ``ctps_dump`` self-test) assert PathTracker /
Localization *logic* that is independent of which field is loaded. They used to
link the production ``WRO2026/routes.cpp``, so an unrelated map edit silently broke
them -- and once the production field collapses to a single spawn node (projection
refactor, #64) they lose the LINE / BLIND / RESET("Wall1") nodes they resolve by
name entirely.

This script emits a small, STABLE fixture graph those tests link instead. The
fixture geometry lives in :file:`field_data_fixture.json` (a frozen copy of the
last multi-node production field: three LINE nodes, three BLIND nodes, and one
RESET node ``Wall1`` at (165, 139) with record ``{axis=y, wall_coord=154,
facing=270}``). The emitted ``routes_fixture.h`` carries the production ``ROUTES_H``
include guard and the identical ``Routes::`` ABI, so the CMake harness
force-includes it ahead of the sketch ``routes.h`` to shadow the production data
for those targets only (the TC16 toy-routes pattern).

The output is committed and frozen. Re-run this ONLY when the ``routes.h`` SCHEMA
changes (a new ``EdgeInfo`` field, an enum value, etc.) makes the committed
fixture stale -- a stale fixture fails the host compile loudly, which is the
signal to regenerate. It is NOT regenerated by CI and is intentionally decoupled
from ``tools/path_planner/field_data.json``.

Run from the repo root::

    uv run --no-sync python WRO2026/test/fixtures/regenerate_routes_fixture.py
"""

from __future__ import annotations

import sys
import warnings
from pathlib import Path
from types import SimpleNamespace

_THIS_DIR = Path(__file__).resolve().parent
_REPO_ROOT = _THIS_DIR.parents[2]  # fixtures -> test -> WRO2026 -> repo root
if str(_REPO_ROOT) not in sys.path:
    sys.path.insert(0, str(_REPO_ROOT))

from tools.path_planner.editor.loader import load_field_json  # noqa: E402
from tools.path_planner.graph_builder import build_graph  # noqa: E402
from tools.path_planner.header_writer import emit_routes  # noqa: E402
from tools.path_planner.planner import (  # noqa: E402
    BlindDecayParams,
    compute_all_pairs_next_hop,
)

_FIXTURE_JSON = _THIS_DIR / "field_data_fixture.json"
_FIXTURE_HEADER = _THIS_DIR / "routes_fixture.h"
_FIXTURE_SOURCE = _THIS_DIR / "routes_fixture.cpp"


def _build_fixture_field_data() -> SimpleNamespace:
    """Load the frozen fixture JSON into a field_data-shaped namespace.

    Mirrors :mod:`tools.path_planner.field_data`'s attribute mapping so the
    emitter sees the same surface it does for the production field. The fixture
    carries no pivots and no per-edge overrides, so ``PIVOT_TURNS`` / ``EDGES``
    are empty.
    """
    data = load_field_json(_FIXTURE_JSON)
    return SimpleNamespace(
        FIELD_MM=data["FIELD_MM"],
        MAP_PNG=data["MAP_PNG"],
        ROBOT_RADIUS_CM=data["ROBOT_RADIUS_CM"],
        BLIND_DECAY_ENABLED=data["BLIND_DECAY_ENABLED"],
        BLIND_DECAY_K=data["BLIND_DECAY_K"],
        BLIND_DECAY_EXPONENT=data["BLIND_DECAY_EXPONENT"],
        BLIND_DECAY_D_REF=data["BLIND_DECAY_D_REF"],
        START_NODE=data["START_NODE"],
        START_HEADING_DEG=data["START_HEADING_DEG"],
        NODES=data["NODES"],
        NODE_TYPES=data["NODE_TYPES"],
        LINE_SEGMENTS=data["LINE_SEGMENTS"],
        BLIND_EDGES=data["BLIND_EDGES"],
        OBSTACLES=data["OBSTACLES"],
        BLIND_PROJECTION_AUTO_SEEK=data.get("blind_projection_auto_seek", True),
        RESET_NODES=data.get("RESET_NODES", {}),
        PIVOT_TURNS=data.get("pivot_turns", []),
        EDGES=[],
    )


def regenerate() -> None:
    fd = _build_fixture_field_data()
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        graph = build_graph(fd)
    next_hop = compute_all_pairs_next_hop(graph, BlindDecayParams.from_field_data(fd))
    emit_routes(
        fd,
        graph,
        next_hop,
        pivot_records=[],
        header_path=_FIXTURE_HEADER,
        source_path=_FIXTURE_SOURCE,
        field_data_source_path=_FIXTURE_JSON,
    )
    print(f"Regenerated host-test fixture routes:")
    print(f"  {_FIXTURE_HEADER}")
    print(f"  {_FIXTURE_SOURCE}")


if __name__ == "__main__":
    regenerate()
